CREATE TABLE IF NOT EXISTS bom ([bom_id] TEXT, [product_id] TEXT, [lot_id] TEXT, [material_name] TEXT, [quantity_required] TEXT);
CREATE TABLE IF NOT EXISTS capa_records ([capa_id] TEXT, [defect_id] TEXT, [order_id] TEXT, [root_cause] TEXT, [corrective_action] TEXT, [preventive_action] TEXT, [status] TEXT, [verified] TEXT);
CREATE TABLE IF NOT EXISTS defect_records ([defect_id] TEXT, [inspection_id] TEXT, [order_id] TEXT, [defect_type] TEXT, [severity] TEXT, [defect_quantity] TEXT, [status] TEXT);
CREATE TABLE IF NOT EXISTS ground_truth ([exception_id] TEXT, [scenario] TEXT, [expected_result] TEXT, [validation_rule] TEXT);
CREATE TABLE IF NOT EXISTS inspection_plans ([plan_id] TEXT, [product_id] TEXT, [inspection_type] TEXT);
CREATE TABLE IF NOT EXISTS inspection_results ([inspection_id] TEXT, [order_id] TEXT, [inspected_quantity] TEXT, [defect_quantity] TEXT, [result] TEXT);
CREATE TABLE IF NOT EXISTS inspection_results_linked ([inspection_id] TEXT, [order_id] TEXT, [inspected_quantity] TEXT, [defect_quantity] TEXT, [result] TEXT, [plan_id] TEXT);
CREATE TABLE IF NOT EXISTS machines ([machine_id] TEXT, [machine_name] TEXT, [machine_type] TEXT, [status] TEXT);
CREATE TABLE IF NOT EXISTS manufacturing_data ([product_id] TEXT, [temperature] TEXT, [pressure] TEXT, [speed] TEXT, [quality] TEXT);
CREATE TABLE IF NOT EXISTS material_consumption ([consumption_id] TEXT, [order_id] TEXT, [lot_id] TEXT, [product_id] TEXT, [quantity_consumed] TEXT);
CREATE TABLE IF NOT EXISTS material_consumption_before_rebuild ([consumption_id] TEXT, [order_id] TEXT, [lot_id] TEXT, [product_id] TEXT, [quantity_consumed] TEXT);
CREATE TABLE IF NOT EXISTS material_consumption_rebuilt ([consumption_id] TEXT, [order_id] TEXT, [lot_id] TEXT, [product_id] TEXT, [quantity_consumed] TEXT);
CREATE TABLE IF NOT EXISTS material_lots ([lot_id] TEXT, [supplier_id] TEXT, [material_name] TEXT, [quantity_received] TEXT, [status] TEXT);
CREATE TABLE IF NOT EXISTS process_steps ([process_step_id] TEXT, [order_id] TEXT, [machine_id] TEXT, [step_name] TEXT, [status] TEXT);
CREATE TABLE IF NOT EXISTS production_orders ([order_id] TEXT, [product_id] TEXT, [quantity_ordered] TEXT, [status] TEXT);
CREATE TABLE IF NOT EXISTS products ([product_id] TEXT, [product_name] TEXT, [category] TEXT, [status] TEXT);
CREATE TABLE IF NOT EXISTS suppliers ([supplier_id] TEXT, [supplier_name] TEXT, [location] TEXT, [status] TEXT);
